using System;using System.Drawing;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed class IconDialog:Form{
 readonly ComboBox mode=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};readonly TrackBar light=new TrackBar(),sat=new TrackBar(),contrast=new TrackBar(),visibility=new TrackBar(),outline=new TrackBar();readonly Button normal=new Button(),accent=new Button(),apply=new Button();readonly Label status=new Label();string normalColor,accentColor;bool busy;
 public IconDialog(){Text="图标颜色与轮廓 · 4.2.1";Font=new Font("Microsoft YaHei UI",10);ClientSize=new Size(620,615);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;Controls.Add(new Label{Text="让图标在壁纸上清楚可见",Font=new Font(Font.FontFamily,16,FontStyle.Bold),Location=new Point(22,18),Size=new Size(575,32)});Controls.Add(new Label{Text="只处理原生界面图标；保留头像、表情与照片原色。",Location=new Point(22,57),Size=new Size(575,26)});mode.Items.AddRange(new object[]{"原色 · 不增强","保留原色并增强","自选普通图标色与强调色"});mode.SetBounds(22,94,575,30);Controls.Add(mode);normalColor=NativeBackground.InkIcons;accentColor=NativeBackground.InkAccent;ColorButton(normal,"普通图标",normalColor,22);ColorButton(accent,"强调图标",accentColor,316);normal.Click+=delegate{Choose(false);};accent.Click+=delegate{Choose(true);};Row("亮度",light,50,160,184);Row("饱和度",sat,0,180,244);Row("对比度",contrast,50,150,304);Row("可见强度 · 保留透明形状",visibility,0,100,364);Row("轮廓加粗 · 保留原有路径",outline,0,100,424);var s=IconEffects.Load();mode.SelectedIndex=s.Mode;light.Value=s.Brightness;sat.Value=s.Saturation;contrast.Value=s.Contrast;visibility.Value=s.Visibility;outline.Value=s.Outline;mode.SelectedIndexChanged+=delegate{Sync();};Sync();apply.Text="保存并应用";apply.SetBounds(22,500,180,36);Controls.Add(apply);apply.Click+=async delegate{await Apply(false);};var reset=new Button{Text="恢复图标原状",Location=new Point(215,500),Size=new Size(180,36)};Controls.Add(reset);reset.Click+=async delegate{await Apply(true);};var edge=new Button{Text="输入区边框…",Location=new Point(408,500),Size=new Size(189,36)};Controls.Add(edge);edge.Click+=delegate{using(var d=new InputDialog())d.ShowDialog(this);};var strong=new Button{Text="清晰预设",Location=new Point(22,548),Size=new Size(180,30)};Controls.Add(strong);strong.Click+=delegate{mode.SelectedIndex=1;light.Value=110;sat.Value=115;contrast.Value=105;visibility.Value=85;outline.Value=35;};status.SetBounds(22,585,575,26);Controls.Add(status);FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy)e.Cancel=true;};}
 void ColorButton(Button b,string label,string value,int x){b.Text=label+"："+value;b.SetBounds(x,140,281,30);Controls.Add(b);}
 void Choose(bool isAccent){string value=isAccent?accentColor:normalColor;using(var d=new StudioColorPicker{FullOpen=true,Color=Palette.IsColor(value)?ColorTranslator.FromHtml(value):Color.White})if(d.ShowDialog(this)==DialogResult.OK){value=String.Format("#{0:X2}{1:X2}{2:X2}",d.Color.R,d.Color.G,d.Color.B);if(isAccent){accentColor=value;accent.Text="强调图标："+value;}else{normalColor=value;normal.Text="普通图标："+value;}mode.SelectedIndex=2;}}
 void Row(string title,TrackBar slider,int min,int max,int y){Controls.Add(new Label{Text=title,Location=new Point(22,y),Size=new Size(450,24)});var value=new Label{Location=new Point(510,y),Size=new Size(86,24),TextAlign=ContentAlignment.TopRight};Controls.Add(value);slider.Minimum=min;slider.Maximum=max;slider.TickStyle=TickStyle.None;slider.SetBounds(14,y+22,590,30);Controls.Add(slider);slider.ValueChanged+=delegate{value.Text=slider.Value+"%";};}
 internal string DraftColor(bool emphasis){return emphasis?accentColor:normalColor;}
 internal void SetDraftColor(bool emphasis,string value){if(emphasis){accentColor=value;accent.Text="强调图标："+value;}else{normalColor=value;normal.Text="普通图标："+value;}mode.SelectedIndex=2;}
 internal void SetDraftClarity(bool originalShape=false){mode.SelectedIndex=2;visibility.Value=originalShape?0:100;outline.Value=originalShape?0:60;}
 internal void SaveDraftOnly(){NativeBackground.InkIcons=normalColor;NativeBackground.InkAccent=accentColor;IconEffects.Save(new IconSettings{Mode=mode.SelectedIndex,Brightness=light.Value,Saturation=sat.Value,Contrast=contrast.Value,Visibility=visibility.Value,Outline=outline.Value});}
 public bool OperationBusy{get{return busy;}}public Task ApplyWorkspace(){return Apply(false);} public void RenderForTest(string path){StartPosition=FormStartPosition.Manual;Location=new Point(-30000,-30000);ShowInTaskbar=false;Show();Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(path);}Close();}
 void Sync(){bool enhance=mode.SelectedIndex==1;light.Enabled=sat.Enabled=contrast.Enabled=enhance;visibility.Enabled=outline.Enabled=mode.SelectedIndex!=0;normal.Enabled=accent.Enabled=mode.SelectedIndex==2;}
 async Task Apply(bool reset){if(busy)return;var old=IconEffects.Load();string oldNormal=NativeBackground.InkIcons,oldAccent=NativeBackground.InkAccent;try{string source=AutoBackground.SavedImage();if(source==null)throw new IOException("请先选择并应用背景。");busy=true;Enabled=false;var s=new IconSettings{Mode=reset?0:mode.SelectedIndex,Brightness=light.Value,Saturation=sat.Value,Contrast=contrast.Value,Visibility=reset?0:visibility.Value,Outline=reset?0:outline.Value};IconEffects.Save(s);NativeBackground.InkIcons=s.Mode==2?normalColor:"original";NativeBackground.InkAccent=s.Mode==2?accentColor:"original";status.Text="正在更新原生 SVG 图标…";for(int attempt=0;;attempt++){bool retry=false;try{await Task.Run(()=>NativeBackground.Apply(source));break;}catch(IOException e){if(attempt>=4||!e.Message.Contains("另一项背景操作"))throw;retry=true;}if(retry)await Task.Delay(600);}if(reset){mode.SelectedIndex=0;visibility.Value=outline.Value=0;}status.Text=reset?"已恢复原始图标与轮廓。":"已保存，切换界面后也会沿用。";}catch(Exception e){IconEffects.Save(old);NativeBackground.InkIcons=oldNormal;NativeBackground.InkAccent=oldAccent;status.Text=e.Message;}finally{busy=false;Enabled=true;}}
}



